/* Approved player-first hierarchy. Scoped so the board, account UI and
   preserved desktop layouts do not inherit unrelated research overrides. */
.research-reference { --op-bg:#07101e; --op-panel:#0b1728; --op-edge:rgba(115,151,199,.23); --op-muted:#96aac7; --op-green:#30e5b1; --op-red:#f0718b; display:grid!important; grid-template-columns:minmax(0,1fr)!important; gap:12px!important; color:#eaf2ff; font-variant-numeric:tabular-nums; min-width:0; }
.research-reference button,.research-reference select { font:inherit; touch-action:manipulation; }
.research-reference button:focus-visible,.research-reference summary:focus-visible,.research-reference select:focus-visible { outline:2px solid #57b4ff!important; outline-offset:3px; }
.op-research-title { display:flex; align-items:center; justify-content:space-between; gap:12px; }
.op-research-title>div>span { font-size:9px; letter-spacing:.12em; color:var(--op-muted); }
.op-research-title h3 { font-size:18px!important; text-transform:none!important; margin:4px 0!important; letter-spacing:-.025em; }
.research-reference .op-follow { display:grid!important; place-items:center; width:44px!important; height:44px!important; min-height:44px!important; padding:0!important; border:1px solid var(--op-edge)!important; border-radius:12px!important; color:var(--op-muted); background:var(--op-panel)!important; }
.research-reference .op-follow[aria-pressed=true] { color:var(--op-green); }
.op-research-filters { display:grid!important; grid-template-columns:repeat(4,minmax(0,1fr))!important; gap:7px!important; position:relative; z-index:30; }
.op-applied-filter { min-width:0; position:relative; }
.op-applied-filter summary { list-style:none; min-height:57px; display:grid; grid-template-columns:minmax(0,1fr) 9px; gap:4px; border:1px solid var(--op-edge); border-radius:9px; padding:8px; background:var(--op-panel); cursor:pointer; }
.op-applied-filter summary::-webkit-details-marker { display:none; }
.op-applied-filter summary>span:first-child { grid-column:1/-1; font-size:10px; color:var(--op-muted); white-space:nowrap; }
.op-applied-filter summary strong { font-size:12px; font-weight:600; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.op-applied-filter summary>span:last-child { color:#53bfed; }
.op-applied-filter[open] summary { border-color:#498fd2; }
.op-filter-editor { position:absolute; z-index:70; top:calc(100% + 7px); left:0; display:grid; gap:10px; width:min(245px,calc(100vw - 40px)); padding:14px; border:1px solid #396294; border-radius:12px; background:#101e32; box-shadow:0 14px 40px #0009; }
.op-applied-filter:nth-last-child(-n+2) .op-filter-editor { right:0; left:auto; }
.op-filter-editor label { font-size:13px; font-weight:700; }
.research-reference .op-filter-editor select { width:100%; min-height:44px; border:1px solid #456184; border-radius:7px; background:#07101e; color:#fff; padding:8px; font-size:16px; }
.op-filter-editor>div { display:flex; gap:8px; }
.research-reference .op-filter-editor button { flex:1; min-height:44px!important; border-radius:7px!important; padding:8px!important; background:#1a344b!important; border:1px solid #476384!important; font-size:13px!important; }
.research-reference .op-filter-editor button[type=submit] { background:#30e5b1!important; color:#041811!important; border-color:#30e5b1!important; font-weight:750; }
.op-filter-editor small { color:#a8bbd4; font-size:11px; }
.op-sample-caption { display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:6px; font-size:11px; color:var(--op-muted); }
.op-sample-caption button { display:flex; align-items:center; gap:5px; min-height:32px; color:#aad9ff; background:none; border:0; }
.op-line-controls { display:grid; grid-template-columns:minmax(130px,.85fr) minmax(0,1.4fr); gap:9px; }
.op-line-stepper { display:grid; grid-template-columns:40px minmax(0,1fr) 40px; align-items:center; border:1px solid var(--op-edge); border-radius:10px; background:#091426; overflow:hidden; }
.research-reference .op-line-stepper button { display:grid!important; place-items:center; width:40px!important; height:48px!important; min-height:48px!important; padding:0!important; background:#102035!important; border:0!important; border-radius:0!important; color:#dce8f9; }
.op-line-number { text-align:center; font-size:21px!important; font-weight:800; padding:0 3px!important; }
.op-side-picker { display:grid; grid-template-columns:1fr 1fr; border:1px solid #337686; border-radius:10px; overflow:hidden; background:linear-gradient(105deg,#0b2629,#081225); }
.research-reference .op-side-picker button { display:grid; place-content:center; gap:2px; min-height:48px!important; padding:5px!important; border:0!important; border-radius:0!important; background:transparent!important; color:var(--op-muted); }
.research-reference .op-side-picker button+button { border-left:1px solid var(--op-edge)!important; }
.op-side-picker button strong { font-size:15px; white-space:nowrap; }
.op-side-picker button span { font-size:9px; }
.op-side-picker button[data-side=OVER] strong { color:var(--op-green); }
.op-side-picker button[data-side=UNDER] strong { color:var(--op-red); }
.research-reference .op-side-picker button[aria-pressed=true] { box-shadow:inset 0 -2px #49ddc1; background:#244e592b!important; }
.op-price-note,.op-research-footnote { font-size:10px!important; line-height:1.55; color:var(--op-muted); margin:0!important; }
.op-price-note button { color:#8aceff; text-decoration:underline; background:none; border:0; }
.op-samples { display:flex; gap:6px; min-width:0; overflow-x:auto; padding:2px 1px 5px; scrollbar-width:thin; }
.research-reference .op-sample { display:grid!important; flex:1 0 70px; gap:3px; min-width:70px!important; min-height:89px!important; padding:9px 6px!important; border:1px solid var(--op-edge)!important; border-radius:10px!important; background:linear-gradient(#101d30,#071222)!important; text-align:center!important; }
.research-reference .op-sample[aria-pressed=true] { border-color:#348ee8!important; box-shadow:inset 0 0 12px #187ed41c; }
.op-sample>span { font-size:10px; white-space:nowrap; color:var(--op-muted); }
.op-sample>strong { font-size:22px; line-height:1.1; letter-spacing:-.045em; }
.op-sample strong[data-tone=positive] { color:var(--op-green); }
.op-sample strong[data-tone=negative] { color:var(--op-red); }
.op-sample strong[data-tone=neutral] { color:#edd27d; }
.op-sample small { font-size:9px; color:#839ab8; }
.op-chart-section { min-width:0; padding:12px; border:1px solid var(--op-edge); border-radius:12px; background:linear-gradient(130deg,#0b1829,#060e1b); }
.op-chart-heading { display:flex; flex-wrap:wrap; align-items:baseline; justify-content:space-between; gap:6px 10px; }
.op-chart-heading h4 { font-size:12px!important; font-weight:650; text-transform:none!important; }
.op-chart-heading>span { font-size:10px; color:#a5b9d2; }
.op-chart-legend { display:flex; justify-content:flex-end; flex-wrap:wrap; gap:12px; font-size:9px; color:#98aac5; margin:9px 0 22px; }
.op-chart-legend span:before { content:''; display:inline-block; width:7px; height:7px; border-radius:2px; margin-right:4px; background:#30e5b1; }
.op-chart-legend span:nth-child(2):before { background:#f0718b; }
.op-chart-legend span:nth-child(3):before { background:#77849e; }
.op-chart-legend span:last-child:before { display:none; }
.op-chart-scroll { overflow-x:auto; scrollbar-width:thin; min-width:0; }
.op-chart-plot { position:relative; display:grid; align-items:end; height:180px; gap:5px; margin-top:15px; border-bottom:1px solid #394963; background:repeating-linear-gradient(to top,transparent 0,transparent 44px,#6784a518 44px,#6784a518 45px); }
.op-chart-column { position:relative; height:100%; display:flex; align-items:flex-end; }
.op-chart-bar { display:block; width:100%; border-radius:3px 3px 0 0; min-height:2px; background:#7887a1; }
.op-chart-bar[data-result=hit] { background:linear-gradient(#4febc2,#08b789); }
.op-chart-bar[data-result=miss] { background:linear-gradient(#f68aa3,#d44972); }
.op-chart-number { position:absolute; left:0; right:0; text-align:center; padding-bottom:4px; font-size:10px; font-weight:700; color:#d7e5f8; }
.op-chart-threshold { position:absolute; left:0; right:0; border-top:2px dashed #efc74d; z-index:2; pointer-events:none; }
.op-chart-threshold>span { position:absolute; right:0; transform:translateY(-100%); padding:1px 4px; background:#1c1d13; color:#f5d95e; font-size:9px; border-radius:3px; }
.op-chart-labels { display:grid; gap:5px; margin-top:7px; }
.op-chart-labels>span { min-width:0; display:grid; gap:3px; text-align:center; font-size:8px; color:#91a5c2; white-space:nowrap; overflow:hidden; }
.op-chart-labels strong { font-weight:500; }
.op-no-history { display:grid; gap:8px; padding:26px 14px; border:1px dashed var(--op-edge); border-radius:10px; color:#aabbd1; font-size:12px; line-height:1.65; }
.op-install-entry { display:flex; align-items:center; justify-content:center; flex-wrap:wrap; gap:12px; padding:20px 16px; color:var(--text-3,#9baec7); font-size:12px; }
.op-install-entry button { display:flex; align-items:center; gap:8px; min-height:44px; border:1px solid #344b69; border-radius:10px; padding:10px 14px; background:#102039; color:#dcecff; font-weight:650; }
.op-install-dialog { position:fixed; inset:0; width:calc(100% - 32px); max-width:460px; max-height:calc(100dvh - 48px); overflow:auto; margin:auto; padding:26px; background:#0b1628; color:#e8f1ff; border:1px solid #3b6692; border-radius:20px; box-shadow:0 24px 90px #0008; }
.op-install-dialog::backdrop { background:#000b; backdrop-filter:blur(6px); }
.op-install-close { position:absolute; right:10px; top:10px; display:grid; place-items:center; width:44px; height:44px; color:#dce9fa; }
.op-install-mark { display:grid; place-items:center; width:58px; height:58px; border-radius:15px; background:#3de8a8; color:#04150e; font-size:23px; font-weight:850; margin-bottom:20px; }
.op-install-dialog h2 { font-size:24px; line-height:1.15; letter-spacing:-.03em; text-transform:none; margin-bottom:12px; }
.op-install-dialog p { font-size:13px; line-height:1.7; color:#a7bbd7; margin:10px 0; }
.op-install-dialog h3 { font-size:14px; margin-top:21px; }
.op-install-primary { min-height:46px; width:100%; border-radius:10px; background:#3de8a8; color:#031e13; font-weight:750; margin-top:10px; }
.op-install-dialog .op-install-note { font-size:11px; }
.op-offline { position:sticky; bottom:72px; z-index:35; padding:10px 16px; background:#493310; color:#ffe8b3; text-align:center; font-size:12px; }
@media(max-width:767px) {
  .player-app-shell .player-cinematic-hero { margin:0!important; border:1px solid #328cba80!important; border-radius:14px!important; padding:12px!important; background:linear-gradient(135deg,#101c35,#071325)!important; }
  .player-app-shell .player-cinematic-hero .ringavatar { width:66px!important; height:66px!important; }
  .player-app-shell .player-cinematic-hero h1 { font-size:22px!important; }
  .player-app-shell .player-line-glance { border-radius:10px!important; }
  .player-app-shell .player-explorer-panel { width:100%!important; min-width:0!important; padding:12px!important; overflow:visible!important; border:1px solid #41618855!important; border-radius:14px!important; background:#07101e!important; }
  .player-app-shell #player-trends { display:block!important; width:100%!important; }
  .player-app-shell .player-section-block { margin-top:14px!important; }
  .player-app-shell .player-market-rail button { min-height:42px!important; font-size:11px!important; border-radius:9px!important; }
  .player-app-shell .player-section-heading h2 { font-size:13px!important; }
}
@media(min-width:768px) { .research-reference { gap:16px!important; } .op-chart-plot { height:240px; } .op-applied-filter summary { min-height:60px; padding:10px 12px; } .op-sample>strong { font-size:27px; } }
@media(display-mode:standalone) { body { padding-top:env(safe-area-inset-top); } .op-install-entry { display:none; } }
@media(prefers-reduced-motion:reduce) { .research-reference * { animation:none!important; transition:none!important; scroll-behavior:auto!important; } }

