      </head>
      <body>
        <a href="#main" className="fixed top-[-60px] left-4 z-[200] rounded-[var(--radius)] bg-[var(--accent)] px-4 py-3 font-semibold text-[var(--accent-ink)] transition-[top] duration-200 focus:top-4">Skip to content</a>
        <DirectionProvider>
          <CommandSearchController />
          <SiteHeader />
          <main id="main" className="pb-14 lg:pb-0">{children}</main>
          <AppInstall />
          <SiteFooter />
          <MobileNav />
        </DirectionProvider>
      </body>
    </html>
  );
}

files.app/mobile-density.css:
/* Mobile density pass for the live prop board.
   Presentation only: keep providers, research, auth, billing and routing untouched. */

@media (max-width: 767px) {
  /* The board controls were consuming too much of the usable iPhone viewport.
     Let them scroll away instead of pinning a large tray above the feed. */
  main .sticky.top-16 {
    position: relative !important;
    top: auto !important;
    z-index: 10 !important;
    gap: 6px !important;
    margin-inline: 0 !important;
    padding: 6px !important;
    border-radius: 10px !important;
  }

  main .sticky.top-16 .rail {
    display: flex !important;
    gap: 6px !important;
    margin-inline: 0 !important;
    padding: 0 0 2px !important;
    overflow-x: auto !important;
    overscroll-behavior-inline: contain;
    scrollbar-width: none;
    -webkit-overflow-scrolling: touch;
  }

  main .sticky.top-16 .rail::-webkit-scrollbar,
  main .sticky.top-16 > div:nth-child(2)::-webkit-scrollbar {
    display: none;
  }

  main .sticky.top-16 .rail button {
    min-height: 32px !important;
    padding-inline: 10px !important;
    border-radius: 8px !important;
    font-size: 11px !important;
  }

  /* Search, Filters and sort controls stay on one compact horizontal row.
     The row scrolls sideways instead of wrapping into a second line. */
  main .sticky.top-16 > div:nth-child(2) {
    flex-wrap: nowrap !important;
    gap: 6px !important;
    overflow-x: auto !important;
    overscroll-behavior-inline: contain;
    scrollbar-width: none;
    -webkit-overflow-scrolling: touch;
  }

  main .sticky.top-16 > div:nth-child(2) > label {
    flex: 0 0 clamp(170px, 49vw, 210px) !important;
    min-width: 170px !important;
  }

  main .sticky.top-16 input[type="search"] {
    min-height: 34px !important;
    height: 34px !important;
    padding-left: 32px !important;
    border-radius: 8px !important;
    font-size: 12px !important;
  }

  main .sticky.top-16 > div:nth-child(2) > button,
  main .sticky.top-16 .board-filter-trigger {
    min-height: 34px !important;
    height: 34px !important;
    padding-inline: 10px !important;
    border-radius: 8px !important;
    font-size: 11px !important;
    white-space: nowrap;
  }

  .board-filter-panel {
    gap: 6px !important;
    padding: 8px !important;
    border-radius: 9px !important;
    max-height: min(46vh, 340px) !important;
  }

  .board-filter-field {
    gap: 4px !important;
  }

  .board-filter-field select,
  .board-filter-reset {
    min-height: 36px !important;
    height: 36px !important;
  }

  /* Reduce dead space above the feed, but only on the live board container. */
  main > div[class*="max-w-"]:has(> .sticky.top-16) {
    padding-top: 14px !important;
    padding-bottom: 66px !important;
  }

  main > div[class*="max-w-"]:has(> .sticky.top-16) > div:first-child {
    margin-bottom: 10px !important;
  }

  main > div[class*="max-w-"]:has(> .sticky.top-16) > div:first-child h1 {
    font-size: 26px !important;
  }

  .board-kicker {
    margin-bottom: 3px !important;
    font-size: 9px !important;
  }

  /* Dense feed cards: preserve all real data but fit materially more props
     on one phone screen. */
  main .face.prop-card-v2 {
    border-radius: 11px !important;
  }

  .prop-card-v2__open {
    gap: 7px !important;
    padding: 9px 10px 6px !important;
  }

  .prop-card-v2__identity {
    min-height: 44px !important;
    gap: 9px !important;
  }

  .prop-card-v2__identity .ringavatar {
    width: 44px !important;
    height: 44px !important;
  }

  .player-portrait-stack {
    min-width: 46px !important;
  }

  .player-portrait-stack .ringavatar + .ringavatar {
    margin-left: -14px !important;
  }

  .prop-card-v2__identity > span:nth-child(2) > span:first-child {
    font-size: 14px !important;
    line-height: 1.1 !important;
  }

  .prop-card-v2__meta {
    margin-top: 2px !important;
    font-size: 10px !important;
    line-height: 1.2 !important;
  }

  .prop-card-v2__identity > span:last-child {
    font-size: 9px !important;
  }

  .prop-card-v2__market-row {
    gap: 10px !important;
    padding-top: 7px !important;
  }

  .prop-card-v2__market-label {
    gap: 0 !important;
  }

  .prop-card-v2__market-label > span:first-child {
    font-size: 11px !important;
  }

  .prop-card-v2__market-label > span:last-child {
    font-size: 9px !important;
    line-height: 1.2 !important;
  }

  .prop-card-v2__line {
    font-size: 23px !important;
  }

  .prop-card-v2__hit {
    padding: 0 10px 7px !important;
  }

  .prop-card-v2__hit > div,
  .prop-card-v2__hit > span {
    gap: 4px !important;
  }

  .prop-card-v2__hit > div > div:first-child {
    font-size: 10px !important;
  }

  .prop-card-v2__hit > div > div:last-child {
    height: 5px !important;
  }

  .prop-card-v2__quotes {
    gap: 6px !important;
    padding: 0 10px 9px !important;
  }

  .prop-card-v2__quote {
    min-height: 38px !important;
    padding-inline: 10px !important;
    border-radius: 8px !important;
    font-size: 11px !important;
  }

  .prop-card-v2__book {
    margin-top: 0 !important;
    font-size: 8px !important;
  }

  /* Tighten the feed rhythm and reclaim a little more viewport from the nav. */
  main .mt-5.grid:has(> .prop-card-v2),
  main .mt-5.grid:has(> .rv) {
    margin-top: 10px !important;
    gap: 8px !important;
  }

  nav[aria-label="Sections"] a {
    min-height: 50px !important;
    gap: 1px !important;
    font-size: 9px !important;
  }

  nav[aria-label="Sections"] svg {
    width: 18px !important;
    height: 18px !important;
  }
}

files.app/mobile-reference-menu.css:
/* Mobile prop-board top controls based on the approved swipeable reference.
   Presentation and filtering only: no provider, auth, billing, or quote contracts change here. */

@media (max-width: 767px) {
  header[data-board="true"] {
    display: none !important;
  }

  .board-shell {
    padding-top: 0 !important;
  }

  .board-toolbar {
    position: sticky !important;
    top: 0 !important;
    z-index: 50 !important;
    gap: 0 !important;
    margin-inline: -12px !important;
    padding: 0 12px 10px !important;
    border: 0 !important;
    border-bottom: 1px solid #202a48 !important;
    border-radius: 0 !important;
    background: #070b18 !important;
    box-shadow: 0 14px 32px rgb(0 0 0 / .34) !important;
    backdrop-filter: blur(22px) saturate(1.12) !important;
  }

  .board-mobile-controls {
    display: grid;
    min-width: 0;
    gap: 10px;
    overflow: hidden;
  }

  .board-mobile-context-row {
    display: flex;
    min-height: 76px;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    margin-inline: -12px;
    padding:
      max(14px, env(safe-area-inset-top))
      14px
      12px;
    background:
      radial-gradient(420px 130px at 8% 120%, rgb(70 75 255 / .76), transparent 72%),
      linear-gradient(180deg, #080b1d 0%, #11163a 58%, #3038e8 100%);
  }

  .board-mobile-context {
    display: flex;
    min-width: 0;
    align-items: center;
    gap: 10px;
    color: #f7f8ff;
  }

  .board-mobile-context__mark {
    display: grid;
    width: 28px;
    height: 28px;
    place-items: center;
    flex: none;
    border: 2px solid #eef1ff;
    border-radius: 6px;
    font-size: 17px;
    line-height: 1;
  }

  .board-mobile-context strong {
    font-size: 22px;
    font-weight: 800;
    letter-spacing: -.025em;
  }

  .board-mobile-context__slash {
    margin-inline: 2px 4px;
    color: #a7add0;
    font-size: 25px;
    font-weight: 700;
  }

  .board-mobile-sport-button {
    display: inline-flex;
    min-height: 42px;
    align-items: center;
    gap: 8px;
    padding: 0 14px;
    border: 1px solid #7890c8;
    border-radius: 18px;
    background: rgb(79 103 160 / .34);
    color: #f2f5ff;
    font-size: 13px;
    font-weight: 800;
    letter-spacing: .02em;
    white-space: nowrap;
  }

  .board-mobile-profile-button {
    display: grid;
    width: 44px;
    height: 44px;
    place-items: center;
    flex: none;
    border: 0;
    border-radius: 999px;
    background: linear-gradient(145deg, #744fff, #4c64ff);
    color: white;
    box-shadow: 0 8px 22px rgb(30 34 118 / .38);
  }

  .board-mobile-sports-rail,
  .board-mobile-filter-rail,
  .board-mobile-metric-rail {
    display: flex;
    min-width: 0;
    gap: 8px;
    overflow-x: auto;
    overscroll-behavior-inline: contain;
    scrollbar-width: none;
    -webkit-overflow-scrolling: touch;
    scroll-snap-type: x proximity;
  }

  .board-mobile-sports-rail::-webkit-scrollbar,
  .board-mobile-filter-rail::-webkit-scrollbar,
  .board-mobile-metric-rail::-webkit-scrollbar {
    display: none;
  }

  .board-mobile-sports-rail {
    margin-top: -2px;
    padding: 0 0 2px;
  }

  .board-mobile-sports-rail button {
    min-height: 36px;
    flex: none;
    padding: 0 13px;
    border: 1px solid #293354;
    border-radius: 12px;
    background: #11172a;
    color: #aeb7d2;
    font-size: 11px;
    font-weight: 750;
    scroll-snap-align: start;
  }

  .board-mobile-sports-rail button[aria-pressed="true"] {
    border-color: #6d95ff;
    background: #182343;
    color: #fff;
    box-shadow: inset 0 0 0 1px rgb(91 139 255 / .14);
  }

  .board-mobile-app-row {
    display: grid;
    grid-template-columns: minmax(0, 1fr) 52px 52px;
    gap: 8px;
    align-items: stretch;
  }

  .board-mobile-app-select,
  .board-mobile-square-button {
    position: relative;
    min-height: 56px;
    border: 1px solid #242c47;
    border-radius: 17px;
    background: #171d33;
    color: #f1f3fb;
    box-shadow: inset 0 1px 0 rgb(255 255 255 / .025);
  }

  .board-mobile-app-select {
    display: flex;
    min-width: 0;
    align-items: center;
    gap: 8px;
    padding: 0 14px;
    overflow: hidden;
  }

  .board-mobile-app-title {
    margin-right: auto;
    font-size: 15px;
    font-weight: 800;
    letter-spacing: -.01em;
  }

  .board-mobile-book-badges {
    display: flex;
    align-items: center;
    gap: 4px;
    flex: none;
  }

  .board-mobile-book-badges > span {
    display: grid;
    width: 27px;
    height: 27px;
    place-items: center;
    border: 1px solid rgb(255 255 255 / .08);
    border-radius: 9px;
    color: #fff;
    font-size: 9px;
    font-weight: 900;
    letter-spacing: -.03em;
    box-shadow: inset 0 1px 0 rgb(255 255 255 / .08);
  }

  .board-mobile-book-badges > span[data-index="0"] {
    background: linear-gradient(145deg, #273451, #44a7a6);
  }

  .board-mobile-book-badges > span[data-index="1"] {
    background: linear-gradient(145deg, #6d2cff, #aa36ff);
  }

  .board-mobile-book-badges > span[data-index="2"] {
    background: linear-gradient(145deg, #caa82f, #3a3320);
  }

  .board-mobile-more-books {
    flex: none;
    padding: 6px 9px;
    border: 1px solid #30384d;
    border-radius: 999px;
    background: #242a38;
    color: #f5f6fa;
    font-size: 11px;
    font-weight: 750;
  }

  .board-mobile-app-select select,
  .board-mobile-filter-pill select {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    cursor: pointer;
    opacity: 0;
  }

  .board-mobile-app-select:focus-within,
  .board-mobile-filter-pill:focus-within {
    border-color: #6c97ff;
    box-shadow: 0 0 0 3px rgb(86 128 255 / .13);
  }

  .board-mobile-square-button {
    display: grid;
    width: 52px;
    place-items: center;
    color: #aab2ca;
  }

  .board-mobile-square-button[aria-pressed="true"] {
    border-color: #608dff;
    background: #192344;
    color: #f7f9ff;
  }

  .board-mobile-search {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    align-items: center;
    gap: 8px;
    min-height: 46px;
    padding: 0 12px;
    border: 1px solid #2c3658;
    border-radius: 14px;
    background: #11172a;
    color: #919bb8;
  }

  .board-mobile-search input {
    min-width: 0;
    height: 42px;
    padding: 0 !important;
    border: 0 !important;
    background: transparent !important;
    box-shadow: none !important;
    color: #f4f6ff !important;
    font-size: 13px !important;
  }

  .board-mobile-filter-rail {
    margin-inline: -12px;
    padding: 0 12px 2px;
  }

  .board-mobile-filter-pill {
    position: relative;
    display: inline-flex;
    min-width: 138px;
    max-width: 190px;
    min-height: 54px;
    align-items: center;
    gap: 9px;
    flex: 0 0 auto;
    padding: 0 13px;
    border: 1px solid #252d48;
    border-radius: 16px;
    background: #1a1f34;
    color: #aab1c6;
    scroll-snap-align: start;
    box-shadow: inset 0 1px 0 rgb(255 255 255 / .018);
  }

  .board-mobile-filter-pill[data-active="true"] {
    border-color: #648fff;
    background: #1a2748;
    color: #f4f6ff;
  }

  .board-mobile-filter-pill > span {
    min-width: 0;
    overflow: hidden;
    flex: 1;
    font-size: 13px;
    font-weight: 700;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .board-mobile-filter-pill > svg {
    flex: none;
  }

  .board-mobile-metric-rail {
    margin-inline: -12px;
    padding: 2px 12px 0;
    border-top: 1px solid #1f2740;
  }

  .board-mobile-metric-rail button {
    display: inline-flex;
    min-width: 92px;
    min-height: 46px;
    align-items: center;
    justify-content: center;
    gap: 7px;
    flex: 0 0 auto;
    padding: 0 11px;
    border: 1px solid #222b47;
    border-radius: 14px;
    background: #0c1120;
    color: #9ea7c0;
    font-size: 13px;
    font-weight: 760;
    scroll-snap-align: start;
  }

  .board-mobile-metric-rail button[aria-pressed="true"] {
    border-color: #5d8dff;
    background: #17223d;
    color: #f8f9ff;
    box-shadow: inset 0 0 0 1px rgb(75 126 255 / .16);
  }

  .board-mobile-metric-count {
    display: grid;
    min-width: 22px;
    height: 22px;
    place-items: center;
    padding-inline: 5px;
    border-radius: 999px;
    background: #4f7ff5;
    color: #fff;
    font-size: 10px;
    font-weight: 900;
  }

  .board-mobile-sort-glyph {
    color: #9099b3;
    font-size: 18px;
    line-height: 1;
  }

  .board-stale {
    margin-top: 8px !important;
  }

  .board-grid {
    margin-top: 10px !important;
  }
}

@media (max-width: 420px) {
  .board-mobile-context {
    gap: 8px;
  }

  .board-mobile-context strong {
    font-size: 20px;
  }

  .board-mobile-context__slash {
    font-size: 22px;
  }

  .board-mobile-sport-button {
    min-height: 40px;
    padding-inline: 11px;
    font-size: 12px;
  }

  .board-mobile-app-row {
    grid-template-columns: minmax(0, 1fr) 48px 48px;
  }

  .board-mobile-square-button {
    width: 48px;
  }

  .board-mobile-book-badges > span:nth-child(3) {
    display: none;
  }

  .board-mobile-filter-pill {
    min-width: 132px;
  }

  .board-mobile-metric-rail button {
    min-width: 86px;
  }
}

files.app/player-shell.css:
/* Premium player-analysis shell. Presentation only; data contracts stay untouched. */

.player-app-shell {
  --player-nav-top: 72px;
}

.player-section-anchor {
  scroll-margin-top: 154px;
}

.player-cinematic-hero {
  min-height: 250px;
  padding: 24px !important;
  background:
    radial-gradient(760px 300px at 92% -4%, rgba(123,130,255,.24), transparent 64%),
    radial-gradient(540px 280px at -4% 110%, rgba(67,211,208,.10), transparent 68%),
    linear-gradient(145deg, rgba(15,20,42,.98), rgba(6,9,20,.99)) !important;
}

.player-cinematic-hero::before {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(90deg, rgba(5,8,18,.20), transparent 42%),
    repeating-linear-gradient(90deg, transparent 0 79px, rgba(255,255,255,.012) 80px);
  opacity: .8;
}

.player-cinematic-hero > * {
  position: relative;
  z-index: 2;
}

.player-identity-row {
  min-height: 118px;
}

.player-cinematic-hero .ringavatar {
  transform: scale(1.06);
  box-shadow:
    0 0 0 4px rgba(123,130,255,.13),
    0 0 0 1px rgba(180,189,255,.32),
    0 22px 54px rgba(0,0,0,.50) !important;
}

.player-line-glance {
  background:
    linear-gradient(135deg, rgba(255,255,255,.05), rgba(255,255,255,.018)) !important;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.04);
  backdrop-filter: blur(20px);
}

.player-section-nav {
  position: sticky;
  top: var(--player-nav-top);
  z-index: 23;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 5px;
  width: min(620px, 100%);
  margin: 16px auto 0;
  padding: 5px;
  border: 1px solid rgba(145,158,255,.14);
  border-radius: 999px;
  background: rgba(7,10,22,.86);
  box-shadow: 0 14px 46px rgba(0,0,0,.32), inset 0 1px 0 rgba(255,255,255,.035);
  backdrop-filter: blur(24px) saturate(1.15);
}

.player-section-nav button {
  min-height: 40px;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: #7f8ba7;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: -.01em;
  cursor: pointer;
  transition: color .2s ease, background-color .2s ease, box-shadow .2s ease, transform .2s ease;
}

.player-section-nav button:hover {
  color: #eef1ff;
  background: rgba(123,130,255,.07);
}

.player-section-nav button:active {
  transform: scale(.97);
}

.player-section-nav button[aria-pressed='true'] {
  color: #fff;
  background: linear-gradient(135deg, #707aff, #5862dc 64%, #4b8eb7);
  box-shadow: 0 8px 24px rgba(65,74,205,.30), inset 0 1px 0 rgba(255,255,255,.16);
}

.player-section-block {
  margin-top: 30px;
}

.player-section-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 13px;
  padding: 0 2px;
}

.player-section-heading h2 {
  margin: 4px 0 0;
  max-width: 720px;
  color: #f7f8ff;
  font-size: clamp(21px, 2.4vw, 30px) !important;
  font-weight: 760;
  line-height: 1.08;
  letter-spacing: -.04em !important;
}

.player-section-kicker {
  color: #818db0;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .15em;
  text-transform: uppercase;
}

.player-section-count {
  flex: none;
  padding: 7px 10px;
  border: 1px solid rgba(145,158,255,.12);
  border-radius: 999px;
  background: rgba(255,255,255,.025);
  color: #8390aa;
  font-size: 10px;
  font-weight: 700;
  white-space: nowrap;
}

.player-market-rail {
  padding: 3px 0 6px;
}

.player-market-rail button {
  min-height: 45px !important;
  padding-inline: 17px !important;
}

.player-explorer-panel {
  overflow: hidden;
  border-radius: 24px !important;
  background:
    radial-gradient(720px 240px at 90% -20%, rgba(112,122,255,.10), transparent 68%),
    rgba(8,12,26,.86) !important;
}

.player-split-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}

.player-split-card {
  position: relative;
  overflow: hidden;
  min-height: 124px;
  padding: 16px;
  border: 1px solid rgba(145,158,255,.13);
  border-radius: 20px;
  background:
    radial-gradient(340px 130px at 100% 0%, rgba(123,130,255,.08), transparent 68%),
    rgba(9,13,28,.82);
  box-shadow: 0 18px 52px rgba(0,0,0,.24), inset 0 1px 0 rgba(255,255,255,.025);
}

.player-split-card::after {
  content: '';
  position: absolute;
  inset: auto 0 0;
  height: 3px;
  background: #55607a;
  opacity: .55;
}

.player-split-card[data-tone='pos']::after {
  background: #48dfb3;
}

.player-split-card[data-tone='neg']::after {
  background: #ff7097;
}

.player-split-card[data-tone='mid']::after {
  background: #f1bd59;
}

.player-split-topline,
.player-split-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.player-split-topline {
  color: #8995af;
  font-size: 11px;
  font-weight: 650;
}

.player-split-card > strong {
  display: block;
  margin-top: 12px;
  color: #f8f9ff;
  font-size: 30px;
  line-height: 1;
  letter-spacing: -.045em;
}

.player-split-card[data-tone='pos'] > strong {
  color: #58e7bd;
}

.player-split-card[data-tone='neg'] > strong {
  color: #ff7d9f;
}

.player-split-card[data-tone='mid'] > strong {
  color: #f3c56d;
}

.player-split-meta {
  margin-top: 11px;
  color: #68758e;
  font-size: 10px;
}

.player-detail-grid > div > [class*='shadow-[var(--shadow-1)]'] {
  margin-top: 0 !important;
  min-height: 100%;
}

.player-back-link {
  color: #77849f !important;
}

.player-back-link:hover {
  color: #f4f6ff !important;
}

@media (min-width: 1024px) {
  .player-cinematic-hero {
    min-height: 274px;
    padding: 30px !important;
  }

  .player-cinematic-hero .ringavatar {
    transform: scale(1.13);
    margin-right: 7px;
  }

  .player-section-nav {
    top: 68px;
  }
}

@media (max-width: 767px) {
  .player-app-shell {
    --player-nav-top: 63px;
    padding-inline: 12px !important;
  }

  .player-section-anchor {
    scroll-margin-top: 130px;
  }

  .player-cinematic-hero {
    min-height: 0;
    padding: 18px !important;
    border-radius: 22px !important;
  }

  .player-identity-row {
    align-items: flex-start !important;
    min-height: 104px;
  }

  .player-cinematic-hero .ringavatar {
    transform: scale(1);
  }

  .player-line-glance {
    margin-top: 15px !important;
    padding: 13px !important;
  }

  .player-section-nav {
    top: 62px;
    width: 100%;
    margin-top: 12px;
    gap: 3px;
    padding: 4px;
    border-radius: 18px;
  }

  .player-section-nav button {
    min-height: 39px;
    padding-inline: 5px;
    border-radius: 14px;
    font-size: 11px;
  }

  .player-section-block {
    margin-top: 24px;
  }

  .player-section-heading {
    align-items: flex-start;
    margin-bottom: 11px;
  }

  .player-section-heading h2 {
    font-size: 21px !important;
  }

  .player-section-count {
    display: none;
  }

  .player-explorer-panel {
    border-radius: 19px !important;
    padding: 14px !important;
  }

  .player-split-grid {
    grid-template-columns: 1fr;
    gap: 9px;
