}

.prop-card-v2__book {
  margin-top: 0 !important;
  max-width: 110px !important;
  font-size: 7.5px !important;
  line-height: 1.15 !important;
  letter-spacing: .045em !important;
}

/* ------------------------------------------------------------ player page */

.player-app-shell {
  max-width: 1260px !important;
}

